def hide_cursor():
    sys.stdout.write('\033[?25l')
    sys.stdout.flush()

def show_cursor():
    sys.stdout.write('\033[?25h')
    sys.stdout.flush()

def type_ansi_text(text, speed=0.012):
    parts = re.split(r'(\033\[.*?m)', text)
    for part in parts:
        if part.startswith('\033['):
            sys.stdout.write(part)
        else:
            for char in part:
                sys.stdout.write(char)
                sys.stdout.flush()
                time.sleep(speed)

def parse_styled_grid(art_lines):
    """
    Parses ANSI-colored art lines into a 2D matrix of (character, ansi_color_code).
    """
    grid = []
    for line in art_lines:
        row_cells = []
        parts = re.split(r'(\033\[.*?m)', line)
        current_color = '\033[0m'
        for part in parts:
            if part.startswith('\033['):
                current_color = part
            else:
                for ch in part:
                    row_cells.append((ch, current_color))
        grid.append(row_cells)
    return grid

def race_dots_left_to_right(grid, start_row=3, col_start=4, frame_delay=0.032):
    """
    Animates the Braille dots in an asynchronous horizontal race from left to right!
    Each row has its own dynamic runner speeding forward, darting ahead, and
    locking the facial features into place as it surges toward the finish line on the right.
    """
    num_rows = len(grid)
    num_cols = max(len(row) for row in grid) if grid else 0
    
    current_heads = [0 for _ in range(num_rows)]
    runner_dots = ['⠂', '⠐', '⠠', '⠄', '⠅', '⠒', '⠔', '⠕', '⠞', '⠶']
    
    while any(current_heads[r] < len(grid[r]) for r in range(num_rows)):
        for r in range(num_rows):
            target_len = len(grid[r])
            if current_heads[r] >= target_len:
                continue
                
            step = 1
            rand_val = random.random()
            if rand_val < 0.28:
                step = 2  # speed surge
            elif rand_val < 0.38 and current_heads[r] > 0:
                step = 0  # momentary hesitation
                
            old_head = current_heads[r]
            new_head = min(target_len, old_head + step)
            
            for c in range(old_head, new_head):
                ch, color = grid[r][c]
                if ch != ' ':
                    sys.stdout.write(f'\033[{start_row + r};{col_start + c}H{color}{ch}\033[0m')
                else:
                    sys.stdout.write(f'\033[{start_row + r};{col_start + c}H ')
                    
            if new_head < target_len:
                lead_ch = random.choice(runner_dots)
                sys.stdout.write(f'\033[{start_row + r};{col_start + new_head}H\033[38;2;255;255;255m{lead_ch}\033[0m')
                
            current_heads[r] = new_head
            
        sys.stdout.flush()
        time.sleep(frame_delay)
        
    for r in range(num_rows):
        for c in range(len(grid[r])):
            ch, color = grid[r][c]
            if ch != ' ':
                sys.stdout.write(f'\033[{start_row + r};{col_start + c}H{color}{ch}\033[0m')
            else:
                sys.stdout.write(f'\033[{start_row + r};{col_start + c}H ')
    sys.stdout.flush()

def animate_terminal():
    os.system('clear')
    hide_cursor()
    
    try:
        print("\n")
        
        start_row = 3
        col_offset = 48
        
        # Parse portrait into a 2D grid
        grid = parse_styled_grid(ascii_art)
        
        # Clear working canvas
        for r in range(start_row, start_row + len(ascii_art) + 2):
            sys.stdout.write(f'\033[{r};1H\033[K')
        sys.stdout.flush()
        
        # Dynamic horizontal race from left to right
        race_dots_left_to_right(grid, start_row=start_row, col_start=4, frame_delay=0.032)
            
        time.sleep(0.12)
        
        # Animate the side-by-side system card
        start_info_row = start_row + 4
        for i, line in enumerate(info_text):
            sys.stdout.write(f'\033[{start_info_row + i};{col_offset}H')
            sys.stdout.flush()
            
            if "41m" in line or "---" in line:
                sys.stdout.write(line)
                sys.stdout.flush()
                time.sleep(0.03)
            else:
                type_ansi_text(line, speed=0.008)
                
        sys.stdout.write(f'\033[{start_row + len(ascii_art) + 2};0H')
        print("\n")
        
    except KeyboardInterrupt:
        pass
    finally:
        show_cursor()

if __name__ == "__main__":
    animate_terminal()
